-- Catalogo real MCU 5.0 (Agesic, ago-2025): reemplaza el catalogo de prueba (15 controles
-- de ejemplo) por la jerarquia real Funcion > Categoria > Subcategoria > Requisito >
-- Control, extraida de docs/mcu-5.0/Marco_de_Ciberseguridad_5.0_72_requisitos.md (72
-- Requisitos, texto de objetivo) cruzada con las planillas 'Perfil comunitario *.xlsx'
-- (mapeo Funcion/Categoria/Subcategoria NIST CSF -> Requisito, y el texto de cada control
-- graduado por nivel 1-4). Un mismo Requisito puede citarse desde varias Subcategorias --
-- eso es fiel al documento fuente, no una duplicacion introducida acá: cada Subcategoria
-- trae su propia copia del control para poder evaluarse de forma independiente.

-- IMPORTANTE: esto reemplaza in-place el catalogo de la version '5.0' (borra funciones/
-- categorias/subcategorias/requisitos/controles existentes vía ON DELETE CASCADE). Sólo es
-- seguro si no hay evaluation_responses/evidence/audit_observations/improvement_plans
-- apuntando a controles de la version vieja -- si un entorno ya tiene evaluaciones cargadas
-- contra el catálogo de prueba anterior, hay que borrarlas antes (son datos de aplicación,
-- no de catálogo, así que esa limpieza no va en una migración de Flyway).
DELETE FROM prisma.catalog_functions WHERE version_id = (
  SELECT id FROM prisma.catalog_versions WHERE version = '5.0'
);

UPDATE prisma.catalog_versions SET label = 'MCU 5.0 (Agesic, 72 requisitos)' WHERE version = '5.0';

-- Las subcategorías reales son oraciones descriptivas (ej. "Se comprenden y gestionan los
-- requisitos legales..."), no etiquetas cortas como en el catálogo de prueba -- varias superan
-- los VARCHAR(200) originales.
ALTER TABLE prisma.catalog_subcategories ALTER COLUMN name TYPE TEXT;





-- 'target_level' pasa a significar el nivel (1-4) al que pertenece este control dentro de
-- su Requisito (modelo acumulativo: un Requisito alcanza el nivel N cuando TODOS sus
-- controles de nivel <= N estan marcados como cumplidos), no una meta individual 1-5 como
-- en el catalogo de prueba anterior.
