INSERT INTO prisma.catalog_categories (id, function_id, code, name, sort_order) VALUES
('043bc5dc-a53b-510f-b50a-51cf767867d0', '34a50668-a418-5ea5-bfed-287aeab9a350', 'GV.OC', 'Contexto organizativo', 0),
('1adba0eb-1cae-5256-a491-cde2408cffaf', '34a50668-a418-5ea5-bfed-287aeab9a350', 'GV.PO', 'Política', 1),
('4fb4838b-537d-5386-879e-b07059d5befd', '34a50668-a418-5ea5-bfed-287aeab9a350', 'GV.RM', 'Estrategia de gestión de riesgos', 2),
('1839eed2-db4c-5574-a442-ba40663f8833', '34a50668-a418-5ea5-bfed-287aeab9a350', 'GV.RR', 'Funciones, responsabilidades y autoridades', 3),
('912d0df7-1e5e-59a1-9cf2-17facca70921', '34a50668-a418-5ea5-bfed-287aeab9a350', 'GV.SC', 'Gestión de riesgos de la cadena de suministro en materia de ciberseguridad.', 4),
