('32bb14c8-dcfe-5590-bc19-cb22dfc82aee', '4f52154f-3465-5593-b31d-9d08558d37d3', 'PR.AA', 'Gestión de identidades, autenticación y control de acceso', 0),
('8a76d90f-b68c-5f34-9634-10c0f22e2a50', '4f52154f-3465-5593-b31d-9d08558d37d3', 'PR.AT', 'Concienciación y capacitación', 1),
('93d2348d-7b8d-52d5-ba75-4878dc55bf60', '4f52154f-3465-5593-b31d-9d08558d37d3', 'PR.DS', 'Seguridad de los datos', 2),
('e1261836-aa7b-5df3-96e5-5455ed7318ce', '4f52154f-3465-5593-b31d-9d08558d37d3', 'PR.IR', 'Resistencia de la infraestructura tecnológica', 3),
('dfdc1ad3-135e-5d80-a699-090bf2de2072', '4f52154f-3465-5593-b31d-9d08558d37d3', 'PR.PS', 'Seguridad de los datos', 4),
('fe58ec1d-01ef-547a-bbcb-e111a37b3c02', '232ce0d1-fcda-52fb-a001-33977ec59ead', 'DE.AE', 'Análisis de eventos adversos', 0),
('98f099c9-27a7-53c3-9bd4-f87a2ce84da6', '232ce0d1-fcda-52fb-a001-33977ec59ead', 'DE.CM', 'Monitoreo continuo', 1),
('93823578-4a91-5c5e-8473-c5e8c5fc5f0a', '4e40ecc6-0470-5555-992a-e221017de008', 'RS.AN', 'Análisis de incidentes', 0),
('6dd5807c-b7fb-51f7-a103-03160105b10b', '4e40ecc6-0470-5555-992a-e221017de008', 'RS.CO', 'Notificación y comunicación de la respuesta al incidente', 1),
('8f83d485-ec49-52f6-9afd-3448f4af1fd4', '4e40ecc6-0470-5555-992a-e221017de008', 'RS.MA', 'Gestión de incidentes', 2),
('4479c5e3-2744-57e1-b4e9-56d735259c4e', '4e40ecc6-0470-5555-992a-e221017de008', 'RS.MI', 'Mitigación de incidentes', 3),
('78201f2c-5b45-56a5-bf2a-9fd132ce38fd', '3f371307-08e4-57ad-b1b3-1511b73776c9', 'RC.CO', 'Comunicación de la recuperación del incidente', 0),
('4edf26ae-0bb9-5a7d-bbbb-4cc87e681009', '3f371307-08e4-57ad-b1b3-1511b73776c9', 'RC.RP', 'Ejecución del Plan de Recuperación de Incidentes', 1);
INSERT INTO prisma.catalog_subcategories (id, category_id, code, name, sort_order) VALUES
('509fcdfc-b37f-5dcd-b06e-cffecc4356b2', '043bc5dc-a53b-510f-b50a-51cf767867d0', 'GV.OC-01', 'Se comprende la misión de la organización y se informa sobre la gestión de riesgos de ciberseguridad.', 0),
('be4191d1-17af-522c-8aca-bfa75fa228fb', '043bc5dc-a53b-510f-b50a-51cf767867d0', 'GV.OC-02', 'Las partes interesadas internas y externas son comprendidas, y sus necesidades y expectativas con respecto a la gestión de riesgos de ciberseguridad son comprendidas y consideradas.', 1),
('aab9aeba-0a0b-53bf-8b9c-52ef2c0339fb', '043bc5dc-a53b-510f-b50a-51cf767867d0', 'GV.OC-03', 'Se comprenden y gestionan los requisitos legales, normativos y contractuales relativos a la ciberseguridad, incluidas las obligaciones en materia de privacidad y libertades civiles.', 2),
('70d5137b-d090-5997-b71c-53c18241b7d1', '043bc5dc-a53b-510f-b50a-51cf767867d0', 'GV.OC-04', 'Se comprenden y comunican los objetivos, las capacidades y los servicios críticos de los que dependen las partes interesadas externas o que esperan de la organización.', 3),
('f3ed2656-f3ee-55c4-b6f8-31da4a6989eb', '043bc5dc-a53b-510f-b50a-51cf767867d0', 'GV.OC-05', 'Se comprenden y comunican los resultados, capacidades y servicios de los que depende la organización.', 4),
('dcbd1335-4ea5-5932-9bc4-a26fc6dd7550', '1adba0eb-1cae-5256-a491-cde2408cffaf', 'GV.PO-01', 'La política de gestión de riesgos de ciberseguridad se establece en base al contexto organizativo, la estrategia de ciberseguridad y las prioridades, y es comunicada y aplicada.', 0),
('7f2a60d6-26d1-51ac-8bbe-8981e7f88587', '1adba0eb-1cae-5256-a491-cde2408cffaf', 'GV.PO-02', 'La política de gestión de riesgos de ciberseguridad se revisa, actualiza,comunica y aplica para reflejar los cambios en los requisitos, las amenazas, la tecnología y la misión de la organización.', 1),
('b3ba84f4-07e3-5546-b49e-1b47c96e92a6', '4fb4838b-537d-5386-879e-b07059d5befd', 'GV.RM-01', 'Los objetivos de la gestión de riesgos son establecidos y acordados por las partes interesadas de la organización.', 0),
('6cb833e7-d3e6-532b-9c7d-69fd4ddc2c34', '4fb4838b-537d-5386-879e-b07059d5befd', 'GV.RM-02', 'Se establecen, se comunican y se mantienen las declaraciones sobre el apetito de riesgo y la tolerancia al riesgo.', 1),
('fb24e8b2-b8a6-56fd-aea5-20aa189f473c', '4fb4838b-537d-5386-879e-b07059d5befd', 'GV.RM-03', 'Las actividades y los resultados de la gestión de riesgos de ciberseguridad se incluyen en los procesos de gestión de riesgos de la empresa.', 2),
('1f44f637-603a-57f3-93c7-461ca43cd9b1', '4fb4838b-537d-5386-879e-b07059d5befd', 'GV.RM-04', 'Se establece y comunica una dirección estratégica que describa las opciones adecuadas de respuesta al riesgo.', 3),
('be2a4670-5a2c-5938-bb9c-b9b14b2e405f', '4fb4838b-537d-5386-879e-b07059d5befd', 'GV.RM-05', 'Se establecen líneas de comunicación en toda la organización para los riesgos de ciberseguridad, lo que incluye a los riesgos de proveedores y otros terceros.', 4),
('d7bdd2c7-ae29-5c37-b313-3e9cff93f5a9', '4fb4838b-537d-5386-879e-b07059d5befd', 'GV.RM-06', 'Se establece y comunica un método estandarizado para calcular, documentar, categorizar y priorizar los riesgos de ciberseguridad.', 5),
('f8a3b5ce-9096-5b12-8408-51b904907674', '4fb4838b-537d-5386-879e-b07059d5befd', 'GV.RM-07', 'Se caracterizan las oportunidades estratégicas (es decir, los riesgos positivos) y se incluyen en las discusiones sobre riesgos de ciberseguridad de la organización.', 6),
('33528d6d-f97d-5fdb-9496-35cc0f97ac80', '1839eed2-db4c-5574-a442-ba40663f8833', 'GV.RR-01', 'El liderazgo organizativo es responsable de los riesgos de ciberseguridad y fomenta una cultura consciente de los riesgos, ética y de mejora continua.', 0),
('1f6b2c41-5332-5c04-bc39-747e00686b94', '1839eed2-db4c-5574-a442-ba40663f8833', 'GV.RR-02', 'Se establecen, comunican, comprenden y aplican las funciones,responsabilidades y autoridades relacionadas con la gestión de riesgos de ciberseguridad.', 1),
('048e31cb-2fb0-5cd2-9bf4-6879919db2c0', '1839eed2-db4c-5574-a442-ba40663f8833', 'GV.RR-03', 'Se asignan recursos adecuados de acuerdo con la estrategia de riesgos de ciberseguridad, las funciones, las responsabilidades y las políticas.', 2),
('b268efbb-9d80-51c2-8757-a1b3c6ea1757', '1839eed2-db4c-5574-a442-ba40663f8833', 'GV.RR-04', 'La ciberseguridad se incluye en las prácticas de recursos humanos.', 3),
('e8aa129d-94b7-597f-abec-09876ab733a8', '912d0df7-1e5e-59a1-9cf2-17facca70921', 'GV.SC-01', 'Las partes interesadas de la organización establecen y acuerdan un programa, estrategia, objetivos, políticas y procesos de gestión de riesgos de ciberseguridad en la cadena de suministro.', 0),
('ad5bc47f-5af7-5a1c-bd20-70a9ce736eae', '912d0df7-1e5e-59a1-9cf2-17facca70921', 'GV.SC-02', 'Se establecen, comunican y coordinan interna y externamente las funciones y responsabilidades de ciberseguridad para proveedores, clientes y colaboradores.', 1),
('0ffab698-bba4-55e5-802f-5fbfe979e47a', '912d0df7-1e5e-59a1-9cf2-17facca70921', 'GV.SC-03', 'La gestión de riesgos de la cadena de suministro en materia de ciberseguridad está integrada en la ciberseguridad y la gestión de riesgos empresariales, la evaluación de riesgos y los procesos de mejora.', 2),
('b61e4edb-0f18-5e47-aa98-e459c19b3346', '912d0df7-1e5e-59a1-9cf2-17facca70921', 'GV.SC-04', 'Los proveedores son conocidos y priorizados por criticidad.', 3),
('c10e72d9-4033-5616-b391-7fe550a52c3b', '912d0df7-1e5e-59a1-9cf2-17facca70921', 'GV.SC-05', 'Los requisitos para abordar los riesgos de ciberseguridad en las cadenas de suministro se establecen, priorizan e integran en contratos y otros tipos de acuerdos con proveedores y otras terceras partes pertinentes.', 4),
('3ef84cae-e1cc-5b46-9efb-8ab4a9527eca', '912d0df7-1e5e-59a1-9cf2-17facca70921', 'GV.SC-06', 'Se llevan a cabo la planificación y la diligencia debida para reducir los riesgos antes de entablar relaciones formales con proveedores u otros terceros.', 5),
('fbd95ab6-bb3a-59d3-bed8-2a59ced97c81', '912d0df7-1e5e-59a1-9cf2-17facca70921', 'GV.SC-07', 'Los riesgos planteados por un proveedor, sus productos y servicios y otros terceros se comprenden, registran, priorizan, evalúan, responden y monitorean a lo largo de la relación.', 6),
('de63ae03-07d8-5427-a493-8613972819ea', '912d0df7-1e5e-59a1-9cf2-17facca70921', 'GV.SC-08', 'Los proveedores pertinentes y otros terceros se incluyen en las actividades de planificación, respuesta y recuperación de incidentes.', 7),
('f5c0739a-3b8e-5bb8-a058-fcb337732236', '912d0df7-1e5e-59a1-9cf2-17facca70921', 'GV.SC-09', 'Las prácticas de seguridad de la cadena de suministro se integran en los programas de ciberseguridad y de gestión de riesgos empresariales, y su rendimiento se monitorea a lo largo del ciclo de vida de los productos y servicios tecnológicos.', 8),
('b386ba3b-8ca8-515c-a696-2ac5129210f8', '912d0df7-1e5e-59a1-9cf2-17facca70921', 'GV.SC-10', 'Los planes de gestión de riesgos de la cadena de suministro en materia de ciberseguridad incluyen disposiciones para las actividades que ocurren después de la conclusión de un acuerdo de colaboración o servicio.', 9),
('4b3c88c8-c1fb-533c-8ac8-310f2df10007', '4d39c854-e0fc-5afe-b17f-1de056cec9dc', 'ID.AM-01', 'Se mantienen inventarios del hardware gestionado por la organización.', 0),
('877a11ed-f453-52ee-89ec-1eb9727eac23', '4d39c854-e0fc-5afe-b17f-1de056cec9dc', 'ID.AM-02', 'Se mantienen inventarios de software, servicios y sistemas gestionados por la organización.', 1),
('33d93708-19ed-5ac0-9993-8daeebe91065', '4d39c854-e0fc-5afe-b17f-1de056cec9dc', 'ID.AM-03', 'Se mantienen representaciones de la comunicación de red autorizada de la organización y de los flujos de datos de red internos y externos.', 2),
('d81e5a64-a054-52ae-9820-52db2d359740', '4d39c854-e0fc-5afe-b17f-1de056cec9dc', 'ID.AM-04', 'Se mantienen inventarios de los servicios prestados por los proveedores.', 3),
('659e0246-abb2-574e-96b1-b85c63e6be85', '4d39c854-e0fc-5afe-b17f-1de056cec9dc', 'ID.AM-05', 'Se priorizan los activos en función de su clasificación, criticidad, recursos e impacto en la misión.', 4),
('b156d90a-0c2c-5a8a-9413-44d3c669128f', '4d39c854-e0fc-5afe-b17f-1de056cec9dc', 'ID.AM-07', 'Se mantienen inventarios de datos y los metadatos correspondientes para los tipos de datos designados.', 5),
('6f0d7f20-1f22-5729-b479-bee9220d947d', '4d39c854-e0fc-5afe-b17f-1de056cec9dc', 'ID.AM-08', 'Los sistemas, el hardware, el software, los servicios y los datos se gestionan durante todo su ciclo de vida.', 6),
('e4c25fb5-d4e6-5644-90d9-8e7172d22cba', '46218f36-911f-5113-8730-ac39444374ff', 'ID.IM-01', 'Las mejoras se identifican a partir de evaluaciones.', 0),
('3dd52136-c59c-5ee0-9823-d07e85963986', '46218f36-911f-5113-8730-ac39444374ff', 'ID.IM-02', 'Las mejoras se identifican a partir de pruebas y ejercicios de seguridad, lo que incluye a los realizados en coordinación con proveedores y terceros pertinentes.', 1),
('1eacbdfc-7f35-58a8-87c5-db885857948d', '46218f36-911f-5113-8730-ac39444374ff', 'ID.IM-03', 'Las mejoras se identifican a partir de la ejecución de procesos, procedimientos y actividades operativos.', 2),
('32855ac9-c7f6-565b-a061-22900fef2b48', '46218f36-911f-5113-8730-ac39444374ff', 'ID.IM-04', 'Se establecen, comunican, mantienen y mejoran los planes de respuesta a incidentes y otros planes de ciberseguridad que afectan a las operaciones.', 3),
('7d820e89-1280-5907-9dd4-b28bf17e3c81', 'c56ee5f1-0cb0-54b7-914f-7c6c7092cb70', 'ID.RA-01', 'Se identifican, validan y registran las vulnerabilidades de los activos.', 0),
('f8b26274-50a3-596d-945a-deacc9780fa8', 'c56ee5f1-0cb0-54b7-914f-7c6c7092cb70', 'ID.RA-02', 'Se recibe información sobre ciberamenazas de foros y fuentes de intercambio de información.', 1),
('79d37fa8-41a3-5098-82e1-c3d62f3a7905', 'c56ee5f1-0cb0-54b7-914f-7c6c7092cb70', 'ID.RA-03', 'Se identifican y registran las amenazas internas y externas a la organización.', 2),
('92f75935-e835-50a1-ac3e-63586d0118a6', 'c56ee5f1-0cb0-54b7-914f-7c6c7092cb70', 'ID.RA-04', 'Se identifican y registran los impactos potenciales y las probabilidades de que las amenazas exploten las vulnerabilidades.', 3),
('15845394-639b-5bf7-8f3e-040eb1ea2811', 'c56ee5f1-0cb0-54b7-914f-7c6c7092cb70', 'ID.RA-05', 'Las amenazas, las vulnerabilidades, las probabilidades y los impactos se utilizan para comprender el riesgo inherente e informar sobre la priorización de la respuesta al riesgo.', 4),
('a432a127-0a13-562f-b966-b674ded13080', 'c56ee5f1-0cb0-54b7-914f-7c6c7092cb70', 'ID.RA-06', 'Se eligen, priorizan, planifican, controlan y comunican las respuestas al riesgo.', 5),
('904293f4-7fb1-58d3-991d-07cb70916dc0', 'c56ee5f1-0cb0-54b7-914f-7c6c7092cb70', 'ID.RA-07', 'Se gestionan los cambios y las excepciones, se evalúa su impacto en el riesgo,se registran y se realiza su seguimiento.', 6),
('83a98ea3-2e9c-51ff-9150-5818c9e008e5', 'c56ee5f1-0cb0-54b7-914f-7c6c7092cb70', 'ID.RA-08', 'Se establecen procesos para recibir, analizar y responder a las divulgaciones de vulnerabilidades.', 7),
('2fd11c6c-b748-5dd8-a319-ec737cc77d1b', 'c56ee5f1-0cb0-54b7-914f-7c6c7092cb70', 'ID.RA-09', 'Se evalúa la autenticidad e integridad del hardware y software antes de su adquisición y uso.', 8),
('5eaa4611-33bf-5c1a-bcf4-0c96179a8516', 'c56ee5f1-0cb0-54b7-914f-7c6c7092cb70', 'ID.RA-10', 'Se evalúan los proveedores críticos antes de su adquisición.', 9),
('6ac7226a-dd02-5bd8-a444-08f5c8ef5fac', '32bb14c8-dcfe-5590-bc19-cb22dfc82aee', 'PR.AA-01', 'La organización gestiona las identidades y credenciales de los usuarios,servicios y equipos autorizados.', 0),
('c840bf6c-a414-51a3-9c2f-bcb3b17bfa03', '32bb14c8-dcfe-5590-bc19-cb22dfc82aee', 'PR.AA-02', 'Las identidades están comprobadas y vinculadas a credenciales basadas en el contexto de las interacciones.', 1),
('4d3ce2d5-4735-5bc1-a56a-47b73b9906e9', '32bb14c8-dcfe-5590-bc19-cb22dfc82aee', 'PR.AA-03', 'Los usuarios, servicios y hardware están autenticados.', 2),
('044594bb-c7a4-5f0a-9dea-83ed0ef2891a', '32bb14c8-dcfe-5590-bc19-cb22dfc82aee', 'PR.AA-04', 'Las afirmaciones de identidad se protegen, transmiten y verifican.', 3),
('faadeccd-49f9-5fa1-8d81-d1da43938262', '32bb14c8-dcfe-5590-bc19-cb22dfc82aee', 'PR.AA-05', 'Los permisos de acceso, los derechos y las autorizaciones se definen en una política, se gestionan, se aplican y se revisan, e incorporan los principios de privilegio mínimo y separación de funciones.', 4),
('06583834-4e9e-5ad6-a905-f7c614058919', '32bb14c8-dcfe-5590-bc19-cb22dfc82aee', 'PR.AA-06', 'El acceso físico a los activos se gestiona, supervisa y aplica de forma proporcional al riesgo.', 5),
('efd55b4c-62cd-5362-a99d-acc9e3fc8f1b', '8a76d90f-b68c-5f34-9634-10c0f22e2a50', 'PR.AT-01', 'Se sensibiliza y capacita al personal para que disponga de los conocimientos y habilidades necesarios para realizar tareas generales teniendo en cuenta los riesgos de ciberseguridad.', 0),
('15f9f2b9-8da4-5f29-a138-c0244c1ae928', '8a76d90f-b68c-5f34-9634-10c0f22e2a50', 'PR.AT-02', 'Se sensibiliza y capacita a las personas que desempeñan funciones especializadas para que posean los conocimientos y aptitudes necesarios para realizar las tareas pertinentes teniendo en cuenta los riesgos de ciberseguridad.', 1),
('f9acd5b2-3ae8-5910-8a7d-c8660ebaa48f', '93d2348d-7b8d-52d5-ba75-4878dc55bf60', 'PR.DS-01', 'La confidencialidad, la integridad y la disponibilidad de los datos en reposo están protegidas.', 0),
('048ee7c4-4468-5089-b618-6f101d502bcc', '93d2348d-7b8d-52d5-ba75-4878dc55bf60', 'PR.DS-02', 'La confidencialidad, la integridad y la disponibilidad de los datos en tránsito están protegidas.', 1),
('615383ed-c786-5e3e-a817-7e2b07c08afa', '93d2348d-7b8d-52d5-ba75-4878dc55bf60', 'PR.DS-10', 'La confidencialidad, la integridad y la disponibilidad de los datos en uso están protegidas.', 2),
('dc9badc4-883e-5ecb-88c0-fe1501f48e4c', '93d2348d-7b8d-52d5-ba75-4878dc55bf60', 'PR.DS-11', 'Se crean, protegen, mantienen y comprueban copias de seguridad de los datos.', 3),
('43a1b47b-77c3-596d-acac-1de8e29dbee1', 'e1261836-aa7b-5df3-96e5-5455ed7318ce', 'PR.IR-01', 'Las redes y los entornos están protegidos contra el acceso lógico y el uso no autorizados.', 0),
('34d68922-5a4d-5f39-a1d0-c4ec434fdf51', 'e1261836-aa7b-5df3-96e5-5455ed7318ce', 'PR.IR-02', 'Los activos tecnológicos de la organización están protegidos de las amenazas del entorno.', 1),
('b030db27-11f0-5484-b85c-5d36fe980797', 'e1261836-aa7b-5df3-96e5-5455ed7318ce', 'PR.IR-03', 'Se implementan mecanismos para lograr los requisitos de resiliencia en situaciones normales y adversas.', 2),
('7b8d8f9d-7fea-50a6-9093-81c806669aeb', 'e1261836-aa7b-5df3-96e5-5455ed7318ce', 'PR.IR-04', 'Se mantiene una capacidad de recursos adecuada para garantizar la disponibilidad.', 3),
('df2b2346-504b-5510-93ba-98845a301597', 'dfdc1ad3-135e-5d80-a699-090bf2de2072', 'PR.PS-01', 'Se establecen y aplican prácticas de gestión de la configuración.', 0),
('a7fd1626-05bb-571b-9dde-c109ae86f705', 'dfdc1ad3-135e-5d80-a699-090bf2de2072', 'PR.PS-02', 'Se mantiene, sustituye y elimina el software en función del riesgo.', 1),
('7a2b0102-6b11-5c11-8f3d-d5237da85798', 'dfdc1ad3-135e-5d80-a699-090bf2de2072', 'PR.PS-03', 'Se mantiene, sustituye y elimina el hardware en función del riesgo.', 2),
('274a5ba3-7b76-5f9b-b3e0-1c71a5ab9abe', 'dfdc1ad3-135e-5d80-a699-090bf2de2072', 'PR.PS-04', 'Se generan registros y se ponen a disposición para una supervisión continua.', 3),
('708efe26-97c2-521c-ade5-cb9bd06ca761', 'dfdc1ad3-135e-5d80-a699-090bf2de2072', 'PR.PS-05', 'Se impide la instalación y la ejecución de software no autorizado.', 4),
('2b167f09-7842-5ab5-ab2c-b14eed281dc0', 'dfdc1ad3-135e-5d80-a699-090bf2de2072', 'PR.PS-06', 'Se integran prácticas seguras de desarrollo de software y se supervisa su rendimiento durante todo el ciclo de vida de desarrollo del software.', 5),
('600fcb0e-6e5b-5145-a121-9fe647adacdd', 'fe58ec1d-01ef-547a-bbcb-e111a37b3c02', 'DE.AE-02', 'Los eventos potencialmente adversos se analizan para comprender mejor las actividades asociadas.', 0),
('38aad25d-47e4-5f89-a5ec-b5238121838e', 'fe58ec1d-01ef-547a-bbcb-e111a37b3c02', 'DE.AE-03', 'Se correlaciona la información procedente de diversas fuentes.', 1),
('056fd0f0-4502-5642-b8aa-ad2e3f543060', 'fe58ec1d-01ef-547a-bbcb-e111a37b3c02', 'DE.AE-04', 'Se comprende el impacto estimado y el alcance de los eventos adversos.', 2),
('c7542a1e-9617-5bb1-82f2-822861369768', 'fe58ec1d-01ef-547a-bbcb-e111a37b3c02', 'DE.AE-06', 'La información sobre eventos adversos se proporciona al personal y a las herramientas autorizadas.', 3),
('e2cce36f-6762-5a93-8709-77b8d3b829cd', 'fe58ec1d-01ef-547a-bbcb-e111a37b3c02', 'DE.AE-07', 'La inteligencia sobre ciberamenazas y otra información contextual se integran en el análisis.', 4),
('5cf64c10-faf3-52e1-9638-19a61dde1f4f', 'fe58ec1d-01ef-547a-bbcb-e111a37b3c02', 'DE.AE-08', 'Se declaran incidentes cuando los eventos adversos cumplen con los criterios de incidente definidos.', 5),
('85e126aa-994c-5914-bf93-473f0c389fbe', '98f099c9-27a7-53c3-9bd4-f87a2ce84da6', 'DE.CM-01', 'Las redes y los servicios de red se monitorean para detectar eventos potencialmente adversos.', 0),
('b3c2c257-3b7d-5161-87be-c973f2fdd8c4', '98f099c9-27a7-53c3-9bd4-f87a2ce84da6', 'DE.CM-02', 'Se monitorea el entorno físico para detectar posibles eventos adversos.', 1),
('13ed782a-cf22-530d-bbec-36f6981b176c', '98f099c9-27a7-53c3-9bd4-f87a2ce84da6', 'DE.CM-03', 'Se monitorea la actividad del personal y el uso de la tecnología para detectar posibles eventos adversos', 2),
('9d1a78b1-01c9-539e-8b58-40a524629e6f', '98f099c9-27a7-53c3-9bd4-f87a2ce84da6', 'DE.CM-06', 'Se monitorean las actividades y los servicios de los proveedores de servicios externos para detectar eventos potencialmente adversos.', 3),
('615e8a78-333d-5f1d-89e1-ae99c66b2490', '98f099c9-27a7-53c3-9bd4-f87a2ce84da6', 'DE.CM-09', 'Se monitorean el hardware y el software informáticos, los entornos de ejecución y sus datos para detectar posibles eventos adversos.', 4),
('43606f8c-ba50-5c02-958c-2b4aca56785e', '93823578-4a91-5c5e-8473-c5e8c5fc5f0a', 'RS.AN-03', 'Se realizan análisis para determinar lo que ocurrió durante un incidente y la causa raíz del mismo.', 0),
('a3e557a9-4773-5d1e-8cc6-c594f9453acb', '93823578-4a91-5c5e-8473-c5e8c5fc5f0a', 'RS.AN-06', 'Se registran las acciones realizadas durante una investigación y se preservan la integridad y la procedencia de los registros.', 1),
('8b032df9-b8a1-5b0e-a48f-ab7118e7ce12', '93823578-4a91-5c5e-8473-c5e8c5fc5f0a', 'RS.AN-07', 'Se recopilan los datos y metadatos del incidente y se preservan su integridad y su procedencia.', 2),
