('600fa8b8-2c02-54cc-84eb-9744a4848c4f', '6dd5807c-b7fb-51f7-a103-03160105b10b', 'RS.CO-02', 'Se notifican los incidentes a las partes interesadas internas y externas.', 0),
('f5f15a2e-d648-522b-a914-b2786101ca30', '6dd5807c-b7fb-51f7-a103-03160105b10b', 'RS.CO-03', 'La información se comparte con las partes interesadas internas y externas designadas.', 1),
('2883a7b0-6a4c-56e2-8f00-921d621a3562', '8f83d485-ec49-52f6-9afd-3448f4af1fd4', 'RS.MA-01', 'Se ejecuta el plan de respuesta a incidentes en coordinación con los terceros pertinentes una vez que se declara un incidente.', 0),
('149138b1-eecd-5ad0-b308-3e7b96a59e21', '8f83d485-ec49-52f6-9afd-3448f4af1fd4', 'RS.MA-02', 'Se clasifican y validan los informes de incidentes.', 1),
('24527a74-ad9d-5c18-b6bf-83dffc065b6f', '8f83d485-ec49-52f6-9afd-3448f4af1fd4', 'RS.MA-03', 'Se clasifican y priorizan los incidentes.', 2),
