('fd84bcdc-3136-5364-97f3-efe1c010c94d', '8f83d485-ec49-52f6-9afd-3448f4af1fd4', 'RS.MA-05', 'Se aplican los criterios para iniciar la recuperación de incidentes.', 4),
('91708b63-b221-5da7-82d9-1232f0ba271f', '4479c5e3-2744-57e1-b4e9-56d735259c4e', 'RS.MI-01', 'Se contienen los incidentes.', 0),
