INSERT INTO prisma.catalog_controls (id, requirement_id, code, description, target_level, sort_order) VALUES
('44cbe0f7-61c6-5f80-801f-52542b83dff9', 'fb95ff7f-3e7e-5298-a2f9-a8427debfa6a', 'PL.1-1', 'Están establecidos los objetivos anuales de seguridad de la información.', 1, 0),
('3128152f-48db-5f2c-a686-fa2b0fc4e654', 'fb95ff7f-3e7e-5298-a2f9-a8427debfa6a', 'PL.1-2', 'Están definidas las acciones para lograr el cumplimiento de los objetivos.', 1, 1),
('940054e8-c276-599e-9543-0638efbaf69a', 'fb95ff7f-3e7e-5298-a2f9-a8427debfa6a', 'PL.1-3', 'Los objetivos forman parte de un plan de acción de seguridad de la información.', 2, 2),
('13a46236-183b-5584-b68f-aa38b0285f79', 'fb95ff7f-3e7e-5298-a2f9-a8427debfa6a', 'PL.1-4', 'Los objetivos están documentados y aprobados por el CSI.', 2, 3),
('858b6ca0-03b0-541a-8558-4fbc61bc91bc', 'fb95ff7f-3e7e-5298-a2f9-a8427debfa6a', 'PL.1-5', 'Los objetivos anuales de seguridad de la información son difundidos al personal y partes interesadas.', 3, 4),
('457e1814-adaa-5cef-b270-bcbb2029aabd', 'fb95ff7f-3e7e-5298-a2f9-a8427debfa6a', 'PL.1-6', 'El plan de acción para cumplir con los objetivos se desarrolla y ejecuta de manera coordinada con los distintos actores de la organización.', 3, 5),
('7fb5aae5-2f74-5118-a151-b5f0a33f62ca', 'fb95ff7f-3e7e-5298-a2f9-a8427debfa6a', 'PL.1-7', 'Se definen indicadores para el seguimiento del cumplimiento de los objetivos.', 3, 6),
('b15e999a-3693-5768-ba8d-bae1a1daa4ea', 'fb95ff7f-3e7e-5298-a2f9-a8427debfa6a', 'PL.1-8', 'Los objetivos se traducen en proyectos o iniciativas de seguridad de la información.', 4, 7),
('9a600678-1652-5d40-b50e-8731ad6bda05', 'fb95ff7f-3e7e-5298-a2f9-a8427debfa6a', 'PL.1-9', 'Se revisa periódicamente el cumplimiento de los objetivos y el avance del plan de acción.', 4, 8),
('2cd176be-d0d4-5aef-9417-cf95b1a6ce16', '014d7780-efea-5be0-a6c3-1bcd643df77f', 'GR.2-1', 'Se identifican los principales riesgos de seguridad de la información, valorando su potencial impacto y su probabilidad de ocurrencia.', 1, 0),
('1a2b3dfa-29bb-59da-8f11-abc2da219b2c', '014d7780-efea-5be0-a6c3-1bcd643df77f', 'GR.2-3', 'Se cuenta con un inventario de riesgos de seguridad de la información que incluye riesgos asociados a todos los activos de información (se incluyen riesgos positivos).', 2, 1),
('bb503e85-dc5c-50a2-9582-4c593fd121e1', '014d7780-efea-5be0-a6c3-1bcd643df77f', 'GR.2-5', 'Se incorporan riesgos vinculados a la cadena de suministro.', 3, 2),
('0b1fc509-bfda-5527-a402-52e0eea75a74', '014d7780-efea-5be0-a6c3-1bcd643df77f', 'GR.2-7', 'Debe revisarse periódicamente la tolerancia al riesgo establecida, y modificarse ante cambios normativos, tecnológicos o necesidades del negocio.', 4, 3),
('d7bb5686-733c-5ec9-826e-05a8e2c4b61b', '42be0e77-168f-5d33-ab9b-e793637e2870', 'CN.1-1', 'Se identifican los requisitos normativos relacionados a seguridad de la información y ciberseguridad, protección de datos personales, acceso a la información pública, propiedad intelectual, y otras obligaciones legales, contractuales o políticas que resulten exigibles para la organización.', 1, 0),
('4ed33765-4619-5ec4-92a8-3b27a0097d50', '42be0e77-168f-5d33-ab9b-e793637e2870', 'CN.1-2', 'El delegado de protección de datos personales trabaja de manera coordinada con el RSI y/o CSI.', 2, 1),
('51693366-3c0d-5632-aba3-21cf9289fcff', '42be0e77-168f-5d33-ab9b-e793637e2870', 'CN.1-3', 'Se han definido procedimientos para incorporar nuevos requisitos legales o normativos cuando sean publicados.', 3, 2),
('37dc734e-a025-5b37-ac28-e1fae8a5bb20', '42be0e77-168f-5d33-ab9b-e793637e2870', 'CN.1-4', 'El resultado es comunicado al RSI y/o al CSI.', 3, 3),
('f43b916b-5757-5764-b8bd-d074fa0dc5fe', '42be0e77-168f-5d33-ab9b-e793637e2870', 'CN.1-5', 'Se realizan auditorías internas para verificar el cumplimiento.', 4, 4),
('900f5c83-c92b-5a25-84d2-cfdfafa86d75', '42be0e77-168f-5d33-ab9b-e793637e2870', 'CN.1-6', 'Los resultados de las revisiones se utilizan para la mejora continua y apoyan a la toma de decisiones.', 4, 5),
('6634684f-42e0-581d-8c39-aa131e451ed7', '57b1dabd-a88a-54f9-978d-a5d4a1ae9c2d', 'PD.1-1', 'Se lleva un inventario actualizado de bases de datos personales, incluyendo responsables, categoría de datos y sistemas que las soportan.', 1, 0),
('2e1e5a1d-0976-5219-acaf-920d5e46c08e', '57b1dabd-a88a-54f9-978d-a5d4a1ae9c2d', 'PD.1-2', 'Todas las bases de datos que contienen datos personales están registradas ante la URCDP.', 1, 1),
('e9de118e-7036-5529-a662-90d10b3072ab', '57b1dabd-a88a-54f9-978d-a5d4a1ae9c2d', 'PD.1-3', 'Se cuenta con un estudio de la normativa vigente que debe cumplir cada base de datos registrada.', 2, 2),
('3f38d26f-8089-578c-825b-7a720191c8d3', '57b1dabd-a88a-54f9-978d-a5d4a1ae9c2d', 'PD.1-4', 'Se realizan revisiones periódicas del cumplimiento legal del tratamiento de datos personales en los sistemas y procesos de la organización.', 3, 3),
('158fdcf2-a6f3-5abc-afb1-314242210cee', '57b1dabd-a88a-54f9-978d-a5d4a1ae9c2d', 'PD.1-5', 'Se implementan medidas correctivas cuando se detectan incumplimientos en materia de legalidad del tratamiento de datos.', 3, 4),
('35b877c5-3040-5b9c-8cfe-871eac9c4327', '57b1dabd-a88a-54f9-978d-a5d4a1ae9c2d', 'PD.1-6', 'Se ha integrado la revisión del cumplimiento legal del tratamiento de datos personales dentro del proceso de auditoría interna.', 4, 5),
('f162ed20-7a8f-5bff-bb36-2c2feeb043c1', '8e431786-d68f-5cd2-8ce9-3f189abfd2e4', 'PD.2-1', 'Se cuenta con mecanismos para recibir solicitudes expresas de los titulares de corrección manual de datos personales.', 1, 0),
('c4a6f074-66ca-562f-ac51-b6516723a2d8', '8e431786-d68f-5cd2-8ce9-3f189abfd2e4', 'PD.2-2', 'La organización establece qué datos personales son necesarios para cada trámite o servicio, y limita su recolección únicamente a esa información.', 1, 1),
('d935b480-cdb2-5d20-a11b-0d22554e336e', '8e431786-d68f-5cd2-8ce9-3f189abfd2e4', 'PD.2-3', 'Se lleva un registro documentado de todas las solicitudes recibidas por parte de los titulares de datos personales, relativas a la actualización, eliminación o rectificación de sus datos, incluyendo el plazo en que cada solicitud fue atendida.', 2, 2),
('e2cc9226-e3b8-5dc6-bcbe-c6ce0efd41b6', '8e431786-d68f-5cd2-8ce9-3f189abfd2e4', 'PD.2-4', 'Cuando el titular de los datos personales se encuentra presente, se procede a validar la exactitud de los datos y, en caso de corresponder, se actualizan los datos en los sistemas correspondientes en ese mismo momento.', 2, 3),
('4e12bfcb-4d46-55b2-84b3-3b8fb86ca39b', '8e431786-d68f-5cd2-8ce9-3f189abfd2e4', 'PD.2-5', 'Los sistemas implementan funcionalidades que requieren a los usuarios la revisión y validación periódica de sus datos personales, con el objetivo de identificar y corregir información inexacta o desactualizada.', 3, 4),
('29ed3314-e437-5d4c-8827-ebc148aa8762', '8e431786-d68f-5cd2-8ce9-3f189abfd2e4', 'PD.2-6', 'Los sistemas que gestionan datos personales registran las modificaciones realizadas, incluyendo la fecha del cambio y la identidad del usuario que lo efectuó.', 3, 5),
('9c8fe7bd-dcac-5fd1-910e-26830b376679', 'cffc83a3-1a72-563c-9fc8-407acb674e62', 'PD.4-1', 'Cuando corresponde, se incluye una cláusula de consentimiento libre, previa e informada en los medios utilizados para recabar los datos personales (formularios, grabaciones, sitios web, etc.).', 1, 0),
('4af97c7f-6148-5d05-8cf1-4c0cae2d533e', 'cffc83a3-1a72-563c-9fc8-407acb674e62', 'PD.4-2', 'Se conservan registros que evidencien el consentimiento otorgado por los titulares, siempre que sea exigido por la normativa.', 1, 1),
('00f94d6d-218f-5ea5-ae48-1b8eed7246e4', 'cffc83a3-1a72-563c-9fc8-407acb674e62', 'PD.4-3', 'Se verifica, previo al tratamiento de datos personales, si el consentimiento del titular es requerido según lo establecido por la normativa vigente.', 2, 2),
('c1c0dcb1-1fbe-5b25-bccb-1959ca9cefde', 'cffc83a3-1a72-563c-9fc8-407acb674e62', 'PD.4-4', 'Los mecanismos que requieren consentimiento informado garantizan que la opción de aceptar o rechazar esté claramente visible y no preseleccionada.', 2, 3),
